'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var dcomputeInertia = require( './../lib/ndarray.js' );


// FIXTURES //

var ROW_MAJOR_DATA = require( './fixtures/row_major.json' );
var COLUMN_MAJOR_DATA = require( './fixtures/column_major.json' );
var OFFSET_ROW_MAJOR_DATA = require( './fixtures/offsets/row_major.json' );
var OFFSET_COLUMN_MAJOR_DATA = require( './fixtures/offsets/column_major.json' );
var NEGATIVE_STRIDES_ROW_MAJOR_DATA = require( './fixtures/negative-strides/row_major.json' );
var NEGATIVE_STRIDES_COLUMN_MAJOR_DATA = require( './fixtures/negative-strides/column_major.json' );
var MIXED_STRIDES_ROW_MAJOR_DATA = require( './fixtures/mixed-strides/row_major.json' );
var MIXED_STRIDES_COLUMN_MAJOR_DATA = require( './fixtures/mixed-strides/column_major.json' );
var LARGE_STRIDES_ROW_MAJOR_DATA = require( './fixtures/large-strides/row_major.json' );
var LARGE_STRIDES_COLUMN_MAJOR_DATA = require( './fixtures/large-strides/column_major.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dcomputeInertia, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 15', function test( t ) {
	t.strictEqual( dcomputeInertia.length, 15, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a fourth argument which is not a supported distance metric', function test( t ) {
	var values;
	var data;
	var i;

	data = ROW_MAJOR_DATA;

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dcomputeInertia( data.M, data.N, data.k, value, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, new Float64Array( data.C ), data.strideC1, data.strideC2, data.offsetC, new Int32Array( data.labels ), data.strideL, data.offsetL );
		};
	}
});

tape( 'the function computes the inertia between data points and their assigned centroids (row-major)', function test( t ) {
	var inertia;
	var data;

	data = ROW_MAJOR_DATA;
	inertia = dcomputeInertia( data.M, data.N, data.k, data.metric, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, new Float64Array( data.C ), data.strideC1, data.strideC2, data.offsetC, new Int32Array( data.labels ), data.strideL, data.offsetL );

	t.strictEqual( inertia, data.expected, 'returns expected value' );
	t.end();
});

